43	/****************************************************************************
44	 * Pre-processor Definitions
45	 ****************************************************************************/
46	
47	#define SDIO_BLOCK_SIZE     512
48	#define SDIO_INIT_MAX_RETRY 10
49	
50	#define SDIO_FUNC_0         0
51	#define SDIO_FUNC_1         1
52	
53	/* SDIO CCCR registers */
54	
55	#define SD_IO_CCCR_FN_ENABLE    0x02
56	#define SD_IO_CCCR_FN_READY     0x03
57	#define SD_IO_CCCR_INT_ENABLE   0x04
58	#define SD_IO_CCCR_BUS_WIDTH    0x07
59	
60	/* SDIO FBR registers */
61	
62	#define SD_IO_FBR_START         0x100
63	
64	/* SDIO block size registers */
65	
66	#define SD_IO_CCCR_BLKSIZEL     0x10
67	#define SD_IO_CCCR_BLKSIZEH     0x11
68	
69	/* SDIO wrapper macros for NuttX SDIO interface */
70	
71	#define SDIO_WRITEFUNC(dev, func, addr, data, len) \
72	    sdio_io_rw_extended((dev), true, (func), (addr), true, (data), (len), 1)
73	
74	#define SDIO_READFUNC(dev, func, addr, data, len) \
75	    sdio_io_rw_extended((dev), false, (func), (addr), true, (data), (len), 1)
76	
77	#define SDIO_READBLOCK(dev, reg, data, blocks) \
78	    sdio_io_rw_extended((dev), false, SDIO_FUNC_1, (reg), true, (data), SDIO_BLOCK_SIZE, (blocks))
79	
80	#define SDIO_WRITEBLOCK(dev, reg, data, blocks) \
81	    sdio_io_rw_extended((dev), true, SDIO_FUNC_1, (reg), true, (data), SDIO_BLOCK_SIZE, (blocks))
82	
83	#define SDIO_SETFREQUENCY(dev, freq) \
84	    ((dev)->clock((dev), CLOCK_SD_TRANSFER_4BIT))
85	
86	#define SDIO_SETBUSWIDTH(dev, width) \
87	    sdio_set_wide_bus(dev)
88	
89	#define SDIO_WAITINT(dev, ticks) \
90	    ((dev)->eventwait(dev))
