121	/****************************************************************************
122	 * Name: hosted_sdio_set_blocksize
123	 *
124	 * Description:
125	 *   Set SDIO function block size.
126	 *
127	 ****************************************************************************/
128	
129	static int hosted_sdio_set_blocksize(struct sdio_dev_s *dev, uint8_t fn,
130	                                     uint16_t size)
131	{
132	    uint8_t lo = size & 0xff;
133	    uint8_t hi = (size >> 8) & 0xff;
134	    uint16_t offset = SD_IO_FBR_START * fn;
135	    int ret;
136	
137	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0,
138	                         offset + SD_IO_CCCR_BLKSIZEL, &lo, 1);
139	    if (ret < 0) {
140	        return ret;
141	    }
142	
143	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0,
144	                         offset + SD_IO_CCCR_BLKSIZEH, &hi, 1);
145	    if (ret < 0) {
146	        return ret;
147	    }
148	
149	    return 0;
150	}
