152	/****************************************************************************
153	 * Name: hosted_sdio_card_fn_init
154	 *
155	 * Description:
156	 *   Initialize SDIO card function 1.
157	 *
158	 ****************************************************************************/
159	
160	static int hosted_sdio_card_fn_init(struct sdio_dev_s *dev)
161	{
162	    uint8_t ioe = 0;
163	    uint8_t ior = 0;
164	    uint8_t ie = 0;
165	    int i;
166	    int ret;
167	
168	    /* Enable function 1 */
169	
170	    ret = SDIO_READFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_FN_ENABLE, &ioe, 1);
171	    if (ret < 0) {
172	        return ret;
173	    }
174	
175	    wlinfo("IOE: 0x%02x\n", ioe);
176	
177	    ioe |= (1 << 1);  /* FUNC1_EN_MASK */
178	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_FN_ENABLE, &ioe, 1);
179	    if (ret < 0) {
180	        return ret;
181	    }
182	
183	    /* Wait for card to become ready */
184	
185	    for (i = 0; i < SDIO_INIT_MAX_RETRY; i++) {
186	        ret = SDIO_READFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_FN_READY, &ior, 1);
187	        if (ret < 0) {
188	            return ret;
189	        }
190	
191	        wlinfo("IOR: 0x%02x\n", ior);
192	        if (ior & (1 << 1)) {
193	            break;
194	        }
195	
196	        usleep(10 * 1000);
197	    }
198	
199	    if (i >= SDIO_INIT_MAX_RETRY) {
200	        wlerr("ERROR: SDIO card failed to become ready\n");
201	        return -ETIMEDOUT;
202	    }
203	
204	    /* Enable interrupts for function 1 and master enable */
205	
206	    ret = SDIO_READFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie, 1);
207	    if (ret < 0) {
208	        return ret;
209	    }
210	
211	    wlinfo("IE: 0x%02x\n", ie);
212	
213	    ie |= (1 << 0) | (1 << 1);  /* Master enable + FUNC1 */
214	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0, SD_IO_CCCR_INT_ENABLE, &ie, 1);
215	    if (ret < 0) {
216	        return ret;
217	    }
218	
219	    /* Set FN0 and FN1 block size to 512 */
220	
221	    ret = hosted_sdio_set_blocksize(dev, SDIO_FUNC_0, SDIO_BLOCK_SIZE);
222	    if (ret < 0) {
223	        return ret;
224	    }
225	
226	    ret = hosted_sdio_set_blocksize(dev, SDIO_FUNC_1, SDIO_BLOCK_SIZE);
227	    if (ret < 0) {
228	        return ret;
229	    }
230	
231	    return 0;
232	}
