238	/****************************************************************************
239	 * Name: hosted_sdio_card_init
240	 *
241	 * Description:
242	 *   Initialize SDIO card.
243	 *
244	 ****************************************************************************/
245	
246	int hosted_sdio_card_init(void *ctx, bool show_config)
247	{
248	    struct hosted_sdio_context *context = (struct hosted_sdio_context *)ctx;
249	    struct sdio_dev_s *dev;
250	    int ret;
251	
252	    if (!context || !context->sdio_dev) {
253	        return -EINVAL;
254	    }
255	
256	    dev = context->sdio_dev;
257	
258	    /* Initialize SDIO bus */
259	
260	    SDIO_SETFREQUENCY(dev, context->clock_freq_khz * 1000);
261	
262	    if (context->bus_width == 4) {
263	        ret = SDIO_SETBUSWIDTH(dev, 4);
264	        if (ret < 0) {
265	            wlerr("ERROR: Failed to set 4-bit bus width: %d\n", ret);
266	            return ret;
267	        }
268	    }
269	
270	    /* Initialize card function */
271	
272	    ret = hosted_sdio_card_fn_init(dev);
273	    if (ret < 0) {
274	        wlerr("ERROR: Failed to initialize SDIO card function: %d\n", ret);
275	        return ret;
276	    }
277	
278	    wlinfo("SDIO card initialized successfully\n");
279	    return 0;
280	}
