365	/****************************************************************************
366	 * Name: hosted_sdio_read_block
367	 *
368	 * Description:
369	 *   Read SDIO block.
370	 *
371	 ****************************************************************************/
372	
373	int hosted_sdio_read_block(void *ctx, uint32_t reg, uint8_t *data,
374	                           uint16_t size, bool lock_required)
375	{
376	    struct hosted_sdio_context *context = (struct hosted_sdio_context *)ctx;
377	    struct sdio_dev_s *dev;
378	    int ret;
379	
380	    if (!context || !context->sdio_dev || !data) {
381	        return -EINVAL;
382	    }
383	
384	    dev = context->sdio_dev;
385	
386	    if (lock_required) {
387	        nxmutex_lock(&context->lock);
388	    }
389	
390	    /* Use block mode transfer */
391	
392	    uint16_t blocks = size / SDIO_BLOCK_SIZE;
393	    uint16_t remainder = size % SDIO_BLOCK_SIZE;
394	
395	    if (blocks > 0) {
396	        ret = SDIO_READBLOCK(dev, reg, data, blocks);
397	        if (ret < 0) {
398	            goto errout;
399	        }
400	    }
401	
402	    if (remainder > 0) {
403	        /* Read remainder using byte mode */
404	
405	        ret = SDIO_READFUNC(dev, SDIO_FUNC_1,
406	                            reg + blocks * SDIO_BLOCK_SIZE,
407	                            data + blocks * SDIO_BLOCK_SIZE,
408	                            remainder);
409	        if (ret < 0) {
410	            goto errout;
411	        }
412	    }
413	
414	    ret = 0;
415	
416	errout:
417	    if (lock_required) {
418	        nxmutex_unlock(&context->lock);
419	    }
420	
421	    return ret;
422	}
