507	/****************************************************************************
508	 * Name: hosted_sdio_init
509	 *
510	 * Description:
511	 *   Initialize SDIO transport and register OSI functions.
512	 *
513	 ****************************************************************************/
514	
515	int hosted_sdio_init(void)
516	{
517	    struct sdio_dev_s *sdio_dev;
518	
519	    /* Allocate SDIO context */
520	
521	    g_sdio_ctx = (struct hosted_sdio_context *)kumm_malloc(
522	                     sizeof(struct hosted_sdio_context));
523	    if (!g_sdio_ctx) {
524	        return -ENOMEM;
525	    }
526	
527	    memset(g_sdio_ctx, 0, sizeof(struct hosted_sdio_context));
528	
529	    /* Initialize SDIO device */
530	
531	    sdio_dev = sdio_initialize(CONFIG_ESP_HOSTED_SDIO_SLOT);
532	    if (!sdio_dev) {
533	        wlerr("ERROR: Failed to initialize SDIO slot %d\n",
534	              CONFIG_ESP_HOSTED_SDIO_SLOT);
535	        kumm_free(g_sdio_ctx);
536	        g_sdio_ctx = NULL;
537	        return -ENODEV;
538	    }
539	
540	    g_sdio_ctx->sdio_dev = sdio_dev;
541	    g_sdio_ctx->clock_freq_khz = CONFIG_ESP_HOSTED_SDIO_FREQ_KHZ;
542	    g_sdio_ctx->bus_width = CONFIG_ESP_HOSTED_SDIO_BUS_WIDTH_4BIT ? 4 : 1;
543	    g_sdio_ctx->slot = CONFIG_ESP_HOSTED_SDIO_SLOT;
544	
545	    nxmutex_init(&g_sdio_ctx->lock);
546	
547	    /* Register SDIO functions in OSI */
548	
549	    g_h.funcs->_h_sdio_card_init = hosted_sdio_card_init;
550	    g_h.funcs->_h_sdio_card_deinit = hosted_sdio_card_deinit;
551	    g_h.funcs->_h_sdio_read_reg = hosted_sdio_read_reg;
552	    g_h.funcs->_h_sdio_write_reg = hosted_sdio_write_reg;
553	    g_h.funcs->_h_sdio_read_block = hosted_sdio_read_block;
554	    g_h.funcs->_h_sdio_write_block = hosted_sdio_write_block;
555	    g_h.funcs->_h_sdio_wait_slave_intr = hosted_sdio_wait_slave_intr;
556	
557	    /* Set bus init/deinit */
558	
559	    g_h.funcs->_h_bus_init = hosted_sdio_bus_init;
560	    g_h.funcs->_h_bus_deinit = hosted_sdio_bus_deinit;
561	
562	    wlinfo("SDIO transport initialized\n");
563	    return 0;
564	}
