566	/****************************************************************************
567	 * Name: hosted_sdio_bus_init
568	 *
569	 * Description:
570	 *   Initialize SDIO bus (called by esp_hosted_init).
571	 *
572	 ****************************************************************************/
573	
574	void *hosted_sdio_bus_init(void)
575	{
576	    int ret;
577	
578	    if (!g_sdio_ctx) {
579	        ret = hosted_sdio_init();
580	        if (ret < 0) {
581	            return NULL;
582	        }
583	    }
584	
585	    /* Initialize card */
586	
587	    ret = hosted_sdio_card_init(g_sdio_ctx, true);
588	    if (ret < 0) {
589	        wlerr("ERROR: SDIO card init failed: %d\n", ret);
590	        return NULL;
591	    }
592	
593	    return g_sdio_ctx;
594	}
595	
596	/****************************************************************************
597	 * Name: hosted_sdio_bus_deinit
598	 *
599	 * Description:
600	 *   Deinitialize SDIO bus.
601	 *
602	 ****************************************************************************/
603	
604	int hosted_sdio_bus_deinit(void *ctx)
605	{
606	    struct hosted_sdio_context *context = (struct hosted_sdio_context *)ctx;
607	
608	    if (context) {
609	        hosted_sdio_card_deinit(context);
610	        nxmutex_destroy(&context->lock);
611	        kumm_free(context);
612	        g_sdio_ctx = NULL;
613	    }
614	
615	    return 0;
616	}
