/****************************************************************************
 * SDMMC Host Controller Driver for ESP32P4
 *
 * This driver implements the NuttX SDIO interface (struct sdio_dev_s) for
 * the DesignWare MCI IP core found on the ESP32P4.
 *
 * Key differences from ESP32S3:
 * - RISC-V architecture (not Xtensa)
 * - Uses HP_SYS_CLKRST for clock/reset (not SYSTEM_* registers)
 * - DMA descriptors are 64 bytes (vs 16 on ESP32S3)
 * - Slot 0 uses IOMUX, slot 1 uses GPIO matrix
 * - Register base: DR_REG_SDHOST_BASE (not DR_REG_SDMMC_BASE)
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/sdio.h>
#include <nuttx/irq.h>
#include <nuttx/kmalloc.h>
#include <nuttx/semaphore.h>
#include <nuttx/spinlock.h>

#include <stdbool.h>
