 *
 ****************************************************************************/

static void esp_sdmmc_blocksetup(struct sdio_dev_s *dev, size_t blocklen,
                                  size_t nblocks)
{
  /* Set block size and byte count */

  sdmmc_ll_set_block_size(blocklen);
  sdmmc_ll_set_data_transfer_len(blocklen * nblocks);
}

/****************************************************************************
 * Name: esp_sdmmc_recvsetup
 *
 * Description:
 *   Set up for a data receive operation.
 *
 ****************************************************************************/

static int esp_sdmmc_recvsetup(struct sdio_dev_s *dev, uint8_t *buffer,
                                size_t nbytes)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;

  priv->dma_tx = false;
  esp_sdmmc_setup_dma_transfer(priv, buffer, nbytes, false);

  return OK;
}

/****************************************************************************
 * Name: esp_sdmmc_sendsetup
 *
 * Description:
 *   Set up for a data send operation.
 *
 ****************************************************************************/

static int esp_sdmmc_sendsetup(struct sdio_dev_s *dev,
                                const uint8_t *buffer, size_t nbytes)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;

  priv->dma_tx = true;
  esp_sdmmc_setup_dma_transfer(priv, (uint8_t *)buffer, nbytes, true);

  return OK;
}

/****************************************************************************
 * Name: esp_sdmmc_cancel
 *
 * Description:
 *   Cancel any pending data transfer.
 *
 ****************************************************************************/

static int esp_sdmmc_cancel(struct sdio_dev_s *dev)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  /* Reset DMA and FIFO */

  sdmmc_ll_reset_dma();
  sdmmc_ll_reset_fifo();

  /* Clear pending events */

  priv->events = 0;
  priv->waitevents = 0;

  spin_unlock_irqrestore(&priv->lock, flags);

  return OK;
}

