/****************************************************************************
 * Event handling
 ****************************************************************************/

static void esp_sdmmc_waitenable(struct sdio_dev_s *dev,
                                  sdio_eventset_t eventset,
                                  uint32_t timeout)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  priv->waitevents = eventset;
  priv->events = 0;

  /* Reset the semaphore to count 0 */

  while (nxsem_trywait(&priv->waitsem) == OK);

  spin_unlock_irqrestore(&priv->lock, flags);
}

static sdio_eventset_t esp_sdmmc_eventwait(struct sdio_dev_s *dev)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  irqstate_t flags;
  sdio_eventset_t events;

  /* Wait for events */

  nxsem_wait(&priv->waitsem);

  flags = spin_lock_irqsave(&priv->lock);
  events = priv->events;
  priv->events = 0;
  priv->waitevents = 0;
  spin_unlock_irqrestore(&priv->lock, flags);

  /* Map to SDIO event set */

  sdio_eventset_t sdio_events = 0;

  if (events & SDMMC_EVENT_CMDDONE)
    {
      sdio_events |= SDIOWAIT_CMDDONE;
    }

  if (events & SDMMC_EVENT_DATADONE)
    {
      sdio_events |= SDIOWAIT_RESPONSEDONE;
    }

  if (events & SDMMC_EVENT_ERROR)
    {
      sdio_events |= SDIOWAIT_ERROR;
    }

  return sdio_events;
}

static void esp_sdmmc_callbackenable(struct sdio_dev_s *dev,
                                      sdio_eventset_t eventset)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;

  priv->cbevents = eventset;
}

static void esp_sdmmc_registercallback(struct sdio_dev_s *dev,
                                        worker_t callback, void *arg)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;

  priv->callback = callback;
  priv->cbarg = arg;
}

