/****************************************************************************
 * Name: sdio_initialize
 *
 * Description:
 *   Initialize SDIO for the given slot.  Returns an SDIO device interface
 *   instance.
 *
 ****************************************************************************/

struct sdio_dev_s *sdio_initialize(int slotno)
{
  struct esp32p4_sdmmc_dev_s *priv;
  irqstate_t flags;

  /* Validate slot number */

  if (slotno < 0 || slotno > 1)
    {
      snerr("ERROR: Invalid SDMMC slot %d\n", slotno);
      return NULL;
    }

#if defined(CONFIG_ESP32P4_SDMMC_SLOT0) || defined(CONFIG_ESP32P4_SDMMC_SLOT1)
  /* Check if the requested slot is enabled */

  if (slotno == 0 && !IS_ENABLED(CONFIG_ESP32P4_SDMMC_SLOT0))
    {
      snerr("ERROR: SDMMC slot 0 not enabled\n");
      return NULL;
    }

  if (slotno == 1 && !IS_ENABLED(CONFIG_ESP32P4_SDMMC_SLOT1))
    {
      snerr("ERROR: SDMMC slot 1 not enabled\n");
      return NULL;
    }
#else
  snerr("ERROR: No SDMMC slots enabled\n");
  return NULL;
#endif

  /* Allocate the device structure */

  priv = kmm_zalloc(sizeof(struct esp32p4_sdmmc_dev_s));
  if (priv == NULL)
    {
      snerr("ERROR: Failed to allocate SDMMC device\n");
      return NULL;
    }

  /* Copy the operations table */

  memcpy(&priv->dev, &g_sdmmc_ops, sizeof(g_sdmmc_ops));

  /* Initialize the slot */

  priv->slot = slotno;

  /* Set up pin configuration for slot 1 */

  if (slotno == 1)
    {
      priv->pin_clk = CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CLK;
      priv->pin_cmd = CONFIG_ESP32P4_SDMMC_SLOT1_PIN_CMD;
      priv->pin_d0  = CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D0;
      priv->pin_d1  = CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D1;
      priv->pin_d2  = CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D2;
      priv->pin_d3  = CONFIG_ESP32P4_SDMMC_SLOT1_PIN_D3;
    }

  /* Set IRQ number */

  priv->irq = ESP_IRQ_SDIO_HOST;

  /* Initialize synchronization primitives */

  spin_lock_init(&priv->lock);
  nxsem_init(&priv->waitsem, 0, 0);

  /* Allocate DMA descriptor (must be 64-byte aligned) */

  priv->dma_desc = kmm_memalign(SDMMC_DMA_DESC_ALIGN,
                                 sizeof(struct sdmmc_dma_desc_s));
  if (priv->dma_desc == NULL)
    {
      snerr("ERROR: Failed to allocate DMA descriptor\n");
      kmm_free(priv);
      return NULL;
    }

  flags = spin_lock_irqsave(&priv->lock);

  /* Enable SDMMC bus clock */

  esp_sdmmc_enable_bus_clock(priv);

  /* Reset the controller */

  esp_sdmmc_reset_controller(priv);

  /* Configure pins */

  esp_sdmmc_configure_pins(priv);

  /* Set initial clock to 400 kHz (identification mode) */

  esp_sdmmc_set_frequency(priv, SDMMC_INIT_FREQ);

  /* Set default bus width to 1-bit */

  SDMMC_REG(SDMMC_CTYPE_OFFSET) = 0;
  priv->buswidth = 1;

  /* Set data timeout */

  sdmmc_ll_set_data_timeout(SDMMC_DEFAULT_DATA_TIMEOUT);

  /* Set response timeout */

  sdmmc_ll_set_response_timeout(SDMMC_DEFAULT_RESPONSE_TIMEOUT);

  /* Debounce */

  SDMMC_REG(SDMMC_DEBNCE_OFFSET) = 0xffffff;

  /* Clear all interrupts */

  SDMMC_REG(SDMMC_RINTSTS_OFFSET) = 0xffffffff;

  /* Disable all interrupts (will be enabled in attach) */

  SDMMC_REG(SDMMC_INTMASK_OFFSET) = 0;

  /* DMA mode */

  SDMMC_REG(SDMMC_CTRL_OFFSET) |= SDMMC_CTRL_DMA_ENABLE;

  /* Enable internal DMA controller (IDMAC) */

  SDMMC_REG(SDMMC_BMOD_OFFSET) |= SDMMC_BMOD_ENABLE;

  spin_unlock_irqrestore(&priv->lock, flags);

  sninfo("SDMMC slot %d initialized\n", slotno);

  return &priv->dev;
}

