/****************************************************************************
 * SDMMC Host Controller Driver for ESP32P4
 *
 * This driver implements the NuttX SDIO interface (struct sdio_dev_s) for
 * the DesignWare MCI IP core found on the ESP32P4.
 *
 * Key differences from ESP32S3:
 * - RISC-V architecture (not Xtensa)
 * - Uses HP_SYS_CLKRST for clock/reset (not SYSTEM_* registers)
 * - DMA descriptors are 64 bytes (vs 16 on ESP32S3)
 * - Slot 0 uses IOMUX, slot 1 uses GPIO matrix
 * - Register base: DR_REG_SDHOST_BASE
 * - Register names use SDHOST_* prefix (not SDMMC_* like ESP32S3)
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/sdio.h>
#include <nuttx/irq.h>
#include <nuttx/kmalloc.h>
#include <nuttx/semaphore.h>
#include <nuttx/spinlock.h>

#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <debug.h>
#include <errno.h>

#include "esp_irq.h"
#include "esp_gpio.h"
#include "riscv_internal.h"

#include "soc/sdmmc_struct.h"
#include "soc/sdmmc_reg.h"
#include "soc/gpio_sig_map.h"
#include "hal/sdmmc_ll.h"
#include "soc/sdmmc_pins.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* DMA descriptor alignment (ESP32P4: 64 bytes) */

#define SDMMC_DMA_DESC_ALIGN    64
#define SDMMC_DMA_MAX_BUF_LEN   4096

/* Default timeouts */

#define SDMMC_DEFAULT_DATA_TIMEOUT     0xffffffu
#define SDMMC_DEFAULT_RESPONSE_TIMEOUT 0xffu

/* Clock source: 160 MHz from PLL */

#define SDMMC_CLK_SRC_FREQ     160000000u

/* SDIO card initialization frequency (400 kHz) */

#define SDMMC_INIT_FREQ        400000u

/* Default SDIO operating frequency */

#ifndef CONFIG_ESP32P4_SDMMC_FREQ_KHZ
#  define CONFIG_ESP32P4_SDMMC_FREQ_KHZ 40000
#endif

#define SDMMC_DEFAULT_FREQ     (CONFIG_ESP32P4_SDMMC_FREQ_KHZ * 1000u)

/* SDMMC event flags for interrupt handler */

#define SDMMC_EVENT_CMDDONE    (1 << 0)
#define SDMMC_EVENT_DATADONE   (1 << 1)
#define SDMMC_EVENT_ERROR      (1 << 2)

/* Macro to access SDHOST registers via the sdmmc_dev_t structure */

#define SDMMC_HW  ((sdmmc_dev_t *)DR_REG_SDHOST_BASE)

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* DMA descriptor structure for ESP32P4 (64 bytes, cache-aligned).
 * This matches the hardware IDMAC descriptor layout.
 */

struct sdmmc_dma_desc_s
{
  volatile uint32_t des0;           /* Control word */
  volatile uint32_t des1;           /* Buffer sizes */
  volatile uint32_t buffer1_ptr;    /* Buffer 1 pointer */
  volatile uint32_t buffer2_ptr;    /* Buffer 2 pointer / next desc */
  volatile uint32_t reserved[12];   /* Padding to 64 bytes */
};

/* DMA descriptor des0 bit definitions */

#define DMA_DESC_OWN        (1u << 31)  /* Descriptor owned by IDMAC */
#define DMA_DESC_CH         (1u << 4)   /* Chain: second address is next desc */
#define DMA_DESC_FS         (1u << 3)   /* First descriptor of chain */
#define DMA_DESC_LD         (1u << 2)   /* Last descriptor of chain */
#define DMA_DESC_ER         (1u << 1)   /* End of ring */

/* SDMMC device structure extending struct sdio_dev_s */

struct esp32p4_sdmmc_dev_s
{
  struct sdio_dev_s dev;            /* NuttX SDIO device (must be first) */

  /* Slot configuration */

  int slot;                         /* Slot number (0 or 1) */
  uint32_t frequency;               /* Current clock frequency */
  uint32_t buswidth;                /* Current bus width (1 or 4) */

  /* Interrupt handling */

  int irq;                          /* IRQ number */
  uint32_t events;                  /* Pending events */
  spinlock_t lock;                  /* Interrupt spinlock */
  sem_t waitsem;                    /* Event wait semaphore */

  /* DMA */

  struct sdmmc_dma_desc_s *dma_desc; /* DMA descriptor */
  size_t dmalen;                    /* DMA transfer length */
  bool dma_tx;                      /* true = TX, false = RX */

  /* Callbacks */

  sdio_eventset_t waitevents;       /* Events we are waiting for */
  sdio_eventset_t cbevents;         /* Callback events */
  sdio_callback_t callback;         /* Event callback */
  void *cbarg;                      /* Callback argument */

  /* Pin configuration for slot 1 (GPIO matrix) */

  int pin_clk;
  int pin_cmd;
  int pin_d0;
  int pin_d1;
  int pin_d2;
  int pin_d3;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

/* SDIO interface methods */

static void esp_sdmmc_reset(struct sdio_dev_s *dev);
static sdio_capset_t esp_sdmmc_capabilities(struct sdio_dev_s *dev);
static sdio_status_t esp_sdmmc_status(struct sdio_dev_s *dev);
static void esp_sdmmc_widebus(struct sdio_dev_s *dev, bool enable);
static void esp_sdmmc_clock(struct sdio_dev_s *dev, enum sdio_clock_e rate);
static bool esp_sdmmc_attach(struct sdio_dev_s *dev);

/* Command interface */

static int esp_sdmmc_sendcmd(struct sdio_dev_s *dev, uint32_t cmd,
                              uint32_t arg);
static void esp_sdmmc_blocksetup(struct sdio_dev_s *dev, size_t blocklen,
                                  size_t nblocks);
static int esp_sdmmc_recvsetup(struct sdio_dev_s *dev, uint8_t *buffer,
                                size_t nbytes);
static int esp_sdmmc_sendsetup(struct sdio_dev_s *dev,
                                const uint8_t *buffer, size_t nbytes);
static int esp_sdmmc_cancel(struct sdio_dev_s *dev);

/* Response handling */

static int esp_sdmmc_waitresponse(struct sdio_dev_s *dev, uint32_t cmd);
static int esp_sdmmc_recv_r1(struct sdio_dev_s *dev, uint32_t *r1);
static int esp_sdmmc_recv_r2(struct sdio_dev_s *dev, uint32_t *r2);
static int esp_sdmmc_recv_r3(struct sdio_dev_s *dev, uint32_t *r3);
static int esp_sdmmc_recv_r4(struct sdio_dev_s *dev, uint32_t *r4);
static int esp_sdmmc_recv_r5(struct sdio_dev_s *dev, uint32_t *r5);
static int esp_sdmmc_recv_r6(struct sdio_dev_s *dev, uint32_t *r6);
static int esp_sdmmc_recv_r7(struct sdio_dev_s *dev, uint32_t *r7);

/* Event handling */

static void esp_sdmmc_waitenable(struct sdio_dev_s *dev,
                                  sdio_eventset_t eventset,
                                  uint32_t timeout);
static sdio_eventset_t esp_sdmmc_eventwait(struct sdio_dev_s *dev);
static void esp_sdmmc_callbackenable(struct sdio_dev_s *dev,
                                      sdio_eventset_t eventset);
static void esp_sdmmc_registercallback(struct sdio_dev_s *dev,
                                        worker_t callback, void *arg);

/* DMA */

static int esp_sdmmc_dmarecvsetup(struct sdio_dev_s *dev,
                                   uint8_t *buffer, size_t buflen);
static int esp_sdmmc_dmasendsetup(struct sdio_dev_s *dev,
                                   const uint8_t *buffer, size_t buflen);

/* Internal helpers */

static int esp_sdmmc_interrupt(int irq, void *context, void *arg);
static void esp_sdmmc_configure_pins(struct esp32p4_sdmmc_dev_s *priv);
static int esp_sdmmc_set_frequency(struct esp32p4_sdmmc_dev_s *priv,
                                    uint32_t freq);
static int esp_sdmmc_wait_cmd_done(struct esp32p4_sdmmc_dev_s *priv,
                                    uint32_t timeout_ms);
static int esp_sdmmc_wait_data_done(struct esp32p4_sdmmc_dev_s *priv,
                                     uint32_t timeout_ms);
static void esp_sdmmc_start_command(struct esp32p4_sdmmc_dev_s *priv,
                                     uint32_t cmd, uint32_t arg);
static void esp_sdmmc_setup_dma_transfer(struct esp32p4_sdmmc_dev_s *priv,
                                          uint8_t *buffer, size_t len,
                                          bool is_tx);

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* SDIO device operations */

static const struct sdio_dev_s g_sdmmc_ops =
{
  .reset           = esp_sdmmc_reset,
  .capabilities    = esp_sdmmc_capabilities,
  .status          = esp_sdmmc_status,
  .widebus         = esp_sdmmc_widebus,
  .clock           = esp_sdmmc_clock,
  .attach          = esp_sdmmc_attach,
  .sendcmd         = esp_sdmmc_sendcmd,
  .blocksetup      = esp_sdmmc_blocksetup,
  .recvsetup       = esp_sdmmc_recvsetup,
  .sendsetup       = esp_sdmmc_sendsetup,
  .cancel          = esp_sdmmc_cancel,
  .waitresponse    = esp_sdmmc_waitresponse,
  .recv_r1         = esp_sdmmc_recv_r1,
  .recv_r2         = esp_sdmmc_recv_r2,
  .recv_r3         = esp_sdmmc_recv_r3,
  .recv_r4         = esp_sdmmc_recv_r4,
  .recv_r5         = esp_sdmmc_recv_r5,
  .recv_r6         = esp_sdmmc_recv_r6,
  .recv_r7         = esp_sdmmc_recv_r7,
  .waitenable      = esp_sdmmc_waitenable,
  .eventwait       = esp_sdmmc_eventwait,
  .callbackenable  = esp_sdmmc_callbackenable,
  .registercallback = esp_sdmmc_registercallback,
  .dmarecvsetup    = esp_sdmmc_dmarecvsetup,
  .dmasendsetup    = esp_sdmmc_dmasendsetup,
  .gotextcsd       = NULL,
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp_sdmmc_configure_pins
 *
 * Description:
 *   Configure GPIO pins for SDMMC slot 1 (GPIO matrix mode).
 *   Slot 0 uses IOMUX and does not need GPIO matrix configuration.
 *
 ****************************************************************************/

static void esp_sdmmc_configure_pins(struct esp32p4_sdmmc_dev_s *priv)
{
  if (priv->slot == 0)
    {
      /* Slot 0 uses IOMUX - no GPIO matrix configuration needed.
       * The pins are fixed and configured by the hardware.
       */

      return;
    }

  /* Slot 1: Configure GPIO matrix pins.
   *
   * CLK - output only (push-pull)
   * CMD - bidirectional (open-drain with pull-up)
   * D0-D3 - bidirectional (open-drain with pull-up)
   *
   * GPIO signal indices from gpio_sig_map.h:
   *   SD_CARD_CCLK_2_PAD_OUT_IDX  = 0  (CLK output)
   *   SD_CARD_CCMD_2_PAD_IN_IDX   = 1  (CMD input)
   *   SD_CARD_CCMD_2_PAD_OUT_IDX  = 1  (CMD output)
   *   SD_CARD_CDATA0_2_PAD_IN_IDX = 2  (D0 input)
   *   SD_CARD_CDATA0_2_PAD_OUT_IDX= 2  (D0 output)
   *   ... etc.
   */

  /* CLK - output only */

  esp_configgpio(priv->pin_clk, OUTPUT | FUNCTION);
  esp_gpio_matrix_out(priv->pin_clk, SD_CARD_CCLK_2_PAD_OUT_IDX,
                      false, false);

  /* CMD - bidirectional (open-drain with pull-up) */

  esp_configgpio(priv->pin_cmd, INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(priv->pin_cmd, SD_CARD_CCMD_2_PAD_OUT_IDX,
                      false, false);
  esp_gpio_matrix_in(priv->pin_cmd, SD_CARD_CCMD_2_PAD_IN_IDX, false);

  /* D0 - bidirectional */

  esp_configgpio(priv->pin_d0, INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(priv->pin_d0, SD_CARD_CDATA0_2_PAD_OUT_IDX,
                      false, false);
  esp_gpio_matrix_in(priv->pin_d0, SD_CARD_CDATA0_2_PAD_IN_IDX, false);

  /* D1 - bidirectional */

  esp_configgpio(priv->pin_d1, INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(priv->pin_d1, SD_CARD_CDATA1_2_PAD_OUT_IDX,
                      false, false);
  esp_gpio_matrix_in(priv->pin_d1, SD_CARD_CDATA1_2_PAD_IN_IDX, false);

  /* D2 - bidirectional */

  esp_configgpio(priv->pin_d2, INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(priv->pin_d2, SD_CARD_CDATA2_2_PAD_OUT_IDX,
                      false, false);
  esp_gpio_matrix_in(priv->pin_d2, SD_CARD_CDATA2_2_PAD_IN_IDX, false);

  /* D3 - bidirectional */

  esp_configgpio(priv->pin_d3, INPUT | OUTPUT | OPEN_DRAIN | PULLUP);
  esp_gpio_matrix_out(priv->pin_d3, SD_CARD_CDATA3_2_PAD_OUT_IDX,
                      false, false);
  esp_gpio_matrix_in(priv->pin_d3, SD_CARD_CDATA3_2_PAD_IN_IDX, false);
}

/****************************************************************************
 * Name: esp_sdmmc_set_frequency
 *
 * Description:
 *   Set the SDMMC clock frequency using the HAL layer.
 *
 ****************************************************************************/

static int esp_sdmmc_set_frequency(struct esp32p4_sdmmc_dev_s *priv,
                                    uint32_t freq)
{
  sdmmc_dev_t *hw = SDMMC_HW;

  if (freq == 0)
    {
      return -EINVAL;
    }

  /* Select clock source */

  sdmmc_ll_select_clk_source(hw, SDMMC_LL_CLK_SRC_DEFAULT);

  /* Calculate divider: source_freq / target_freq */

  uint32_t divider = (SDMMC_CLK_SRC_FREQ + freq - 1) / freq;
  if (divider < 1)
    {
      divider = 1;
    }

  /* Set card clock divider and enable */

  sdmmc_ll_set_card_clock_div(hw, priv->slot, divider);
  sdmmc_ll_enable_card_clock(hw, priv->slot, true);

  priv->frequency = freq;
  return OK;
}

/****************************************************************************
 * Name: esp_sdmmc_wait_cmd_done
 *
 * Description:
 *   Wait for command done interrupt with timeout.
 *
 ****************************************************************************/

static int esp_sdmmc_wait_cmd_done(struct esp32p4_sdmmc_dev_s *priv,
                                    uint32_t timeout_ms)
{
  uint32_t start = clock_systime_ticks();
  uint32_t ticks = MSEC2TICK(timeout_ms);
  sdmmc_dev_t *hw = SDMMC_HW;

  while ((clock_systime_ticks() - start) < ticks)
    {
      uint32_t rintsts = hw->rintsts.val;
      if (rintsts & SDMMC_LL_EVENT_CMD_DONE)
        {
          /* Clear the interrupt */

          hw->rintsts.val = SDMMC_LL_EVENT_CMD_DONE;
          return OK;
        }

      up_udelay(10);
    }

  snerr("ERROR: CMD done timeout\n");
  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: esp_sdmmc_wait_data_done
 *
 * Description:
 *   Wait for data transfer done interrupt with timeout.
 *
 ****************************************************************************/

static int esp_sdmmc_wait_data_done(struct esp32p4_sdmmc_dev_s *priv,
                                     uint32_t timeout_ms)
{
  uint32_t start = clock_systime_ticks();
  uint32_t ticks = MSEC2TICK(timeout_ms);
  sdmmc_dev_t *hw = SDMMC_HW;

  while ((clock_systime_ticks() - start) < ticks)
    {
      uint32_t rintsts = hw->rintsts.val;
      if (rintsts & SDMMC_LL_EVENT_DATA_OVER)
        {
          /* Clear the interrupt */

          hw->rintsts.val = SDMMC_LL_EVENT_DATA_OVER;
          return OK;
        }

      up_udelay(10);
    }

  snerr("ERROR: Data done timeout\n");
  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: esp_sdmmc_start_command
 *
 * Description:
 *   Start an SDMMC command using the HAL layer.
 *
 ****************************************************************************/

static void esp_sdmmc_start_command(struct esp32p4_sdmmc_dev_s *priv,
                                     uint32_t cmdreg, uint32_t arg)
{
  sdmmc_dev_t *hw = SDMMC_HW;

  /* Set command argument */

  hw->cmdarg.val = arg;

  /* Start command (set start_cmd bit) */

  hw->cmd.val = cmdreg | SDHOST_START_CMD;
}

/****************************************************************************
 * Name: esp_sdmmc_setup_dma_transfer
 *
 * Description:
 *   Set up DMA descriptors for a data transfer using the internal DMA
 *   controller (IDMAC).
 *
 ****************************************************************************/

static void esp_sdmmc_setup_dma_transfer(struct esp32p4_sdmmc_dev_s *priv,
                                          uint8_t *buffer, size_t len,
                                          bool is_tx)
{
  struct sdmmc_dma_desc_s *desc = priv->dma_desc;
  sdmmc_dev_t *hw = SDMMC_HW;

  /* Configure DMA descriptor */

  memset(desc, 0, sizeof(*desc));

  desc->des0 = DMA_DESC_OWN | DMA_DESC_FS | DMA_DESC_LD;
  if (is_tx)
    {
      desc->des0 |= DMA_DESC_CH;
    }

  desc->des1 = len & 0x1fffu;  /* Buffer 1 size (13 bits) */
  desc->buffer1_ptr = (uint32_t)buffer;
  desc->buffer2_ptr = 0;  /* No second buffer (single descriptor) */

  /* Set data transfer length */

  hw->bytcnt.val = len;
  hw->blksiz.val = SDMMC_DMA_MAX_BUF_LEN;

  /* Point DMA to descriptor */

  hw->dbaddr.val = (uint32_t)desc;

  /* Start DMA by writing to PLDMND */

  hw->pldmnd.val = 1;
}

/****************************************************************************
 * Name: esp_sdmmc_interrupt
 *
 * Description:
 *   SDMMC interrupt handler.
 *
 ****************************************************************************/

static int esp_sdmmc_interrupt(int irq, void *context, void *arg)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)arg;
  sdmmc_dev_t *hw = SDMMC_HW;
  uint32_t status = hw->rintsts.val;
  irqstate_t flags;
  bool post = false;

  flags = spin_lock_irqsave(&priv->lock);

  /* Check for command done */

  if (status & SDMMC_LL_EVENT_CMD_DONE)
    {
      hw->rintsts.val = SDMMC_LL_EVENT_CMD_DONE;
      priv->events |= SDMMC_EVENT_CMDDONE;

      if (priv->waitevents & SDIOWAIT_CMDDONE)
        {
          post = true;
        }
    }

  /* Check for data over (transfer complete) */

  if (status & SDMMC_LL_EVENT_DATA_OVER)
    {
      hw->rintsts.val = SDMMC_LL_EVENT_DATA_OVER;
      priv->events |= SDMMC_EVENT_DATADONE;

      if (priv->waitevents & SDIOWAIT_RESPONSEDONE)
        {
          post = true;
        }
    }

  /* Check for errors */

  if (status & (SDMMC_LL_EVENT_RCRC | SDMMC_LL_EVENT_DCRC |
                SDMMC_LL_EVENT_RTO | SDMMC_LL_EVENT_DTO |
                SDMMC_LL_EVENT_SBE | SDMMC_LL_EVENT_EBE))
    {
      hw->rintsts.val = status &
        (SDMMC_LL_EVENT_RCRC | SDMMC_LL_EVENT_DCRC |
         SDMMC_LL_EVENT_RTO | SDMMC_LL_EVENT_DTO |
         SDMMC_LL_EVENT_SBE | SDMMC_LL_EVENT_EBE);

      priv->events |= SDMMC_EVENT_ERROR;

      if (priv->waitevents & SDIOWAIT_ERROR)
        {
          post = true;
        }
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  /* Post semaphore if we have a matching event */

  if (post)
    {
      nxsem_post(&priv->waitsem);
    }

  /* Call registered callback if enabled */

  if (priv->callback && (priv->events & priv->cbevents))
    {
      priv->callback(&priv->dev, priv->cbarg);
    }

  return OK;
}

/****************************************************************************
 * SDIO Interface Methods
 ****************************************************************************/

/****************************************************************************
 * Name: esp_sdmmc_reset
 *
 * Description:
 *   Reset the SDIO interface.
 *
 ****************************************************************************/

static void esp_sdmmc_reset(struct sdio_dev_s *dev)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  sdmmc_dev_t *hw = SDMMC_HW;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  /* Reset controller, DMA, and FIFO via HAL */

  sdmmc_ll_reset_controller(hw);
  sdmmc_ll_reset_dma(hw);
  sdmmc_ll_reset_fifo(hw);

  /* Clear pending events */

  priv->events = 0;
  priv->waitevents = 0;

  spin_unlock_irqrestore(&priv->lock, flags);
}

/****************************************************************************
 * Name: esp_sdmmc_capabilities
 *
 * Description:
 *   Report capabilities of the SDIO interface.
 *
 ****************************************************************************/

static sdio_capset_t esp_sdmmc_capabilities(struct sdio_dev_s *dev)
{
  sdio_capset_t caps = {0};

  caps.widebus = true;   /* 4-bit bus supported */
  caps.highspeed = true; /* High-speed mode supported */
  caps.dmamode = true;   /* DMA supported */
  caps.writesubmit = true;

  return caps;
}

/****************************************************************************
 * Name: esp_sdmmc_status
 *
 * Description:
 *   Report SDIO interface status.
 *
 ****************************************************************************/

static sdio_status_t esp_sdmmc_status(struct sdio_dev_s *dev)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  sdmmc_dev_t *hw = SDMMC_HW;
  sdio_status_t status = {0};

  /* Check card detect (active low) */

  uint32_t cdetect = hw->cdetect.val;
  if (!(cdetect & (1 << priv->slot)))
    {
      status.inserted = true;
    }

  return status;
}

/****************************************************************************
 * Name: esp_sdmmc_widebus
 *
 * Description:
 *   Enable/disable wide (4-bit) bus mode.
 *
 ****************************************************************************/

static void esp_sdmmc_widebus(struct sdio_dev_s *dev, bool enable)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  sdmmc_dev_t *hw = SDMMC_HW;

  if (enable)
    {
      hw->ctype.val |= (1 << priv->slot);
      priv->buswidth = 4;
    }
  else
    {
      hw->ctype.val &= ~(1 << priv->slot);
      priv->buswidth = 1;
    }
}

/****************************************************************************
 * Name: esp_sdmmc_clock
 *
 * Description:
 *   Set the SDIO clock frequency.
 *
 ****************************************************************************/

static void esp_sdmmc_clock(struct sdio_dev_s *dev, enum sdio_clock_e rate)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;

  switch (rate)
    {
      case SDIO_CLOCK_400KHZ:
        esp_sdmmc_set_frequency(priv, 400000);
        break;

      case SDIO_CLOCK_25MHZ:
        esp_sdmmc_set_frequency(priv, 25000000);
        break;

      case SDIO_CLOCK_50MHZ:
        esp_sdmmc_set_frequency(priv, 50000000);
        break;

      default:
        esp_sdmmc_set_frequency(priv, SDMMC_DEFAULT_FREQ);
        break;
    }
}

/****************************************************************************
 * Name: esp_sdmmc_attach
 *
 * Description:
 *   Attach and enable SDIO interrupt.
 *
 ****************************************************************************/

static bool esp_sdmmc_attach(struct sdio_dev_s *dev)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  sdmmc_dev_t *hw = SDMMC_HW;

  /* Attach the interrupt handler */

  irq_attach(priv->irq, esp_sdmmc_interrupt, priv);

  /* Enable the interrupt at the CPU level */

  up_enable_irq(priv->irq);

  /* Enable specific SDMMC interrupts:
   * - Command done
   * - Data over
   * - Errors (CRC, timeout, etc.)
   */

  uint32_t intmask = SDMMC_LL_EVENT_CMD_DONE |
                     SDMMC_LL_EVENT_DATA_OVER |
                     SDMMC_LL_EVENT_RCRC |
                     SDMMC_LL_EVENT_DCRC |
                     SDMMC_LL_EVENT_RTO |
                     SDMMC_LL_EVENT_DTO |
                     SDMMC_LL_EVENT_SBE |
                     SDMMC_LL_EVENT_EBE;

  hw->intmask.val = intmask;

  /* Enable global interrupt */

  hw->ctrl.val |= SDHOST_INT_ENABLE;

  return true;
}

/****************************************************************************
 * Name: esp_sdmmc_sendcmd
 *
 * Description:
 *   Send an SDMMC command.
 *
 ****************************************************************************/

static int esp_sdmmc_sendcmd(struct sdio_dev_s *dev, uint32_t cmd,
                              uint32_t arg)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  sdmmc_dev_t *hw = SDMMC_HW;
  uint32_t cmdreg = 0;
  int ret;

  /* Build the command register value */

  /* Command index (bits 5:0) */

  cmdreg |= (MMCSD_CMDINDEX(cmd) & 0x3fu) << SDHOST_CMD_INDEX_S;

  /* Response type */

  if (MMCSD_CMDRESP(cmd) == MMCSD_R1 || MMCSD_CMDRESP(cmd) == MMCSD_R5 ||
      MMCSD_CMDRESP(cmd) == MMCSD_R6 || MMCSD_CMDRESP(cmd) == MMCSD_R7)
    {
      cmdreg |= SDHOST_RESPONSE_EXPECT;    /* Expect short response */
      cmdreg |= SDHOST_CHECK_RESPONSE_CRC; /* Check response CRC */
    }
  else if (MMCSD_CMDRESP(cmd) == MMCSD_R2)
    {
      cmdreg |= SDHOST_RESPONSE_EXPECT;    /* Expect response (136-bit) */
      cmdreg |= SDHOST_RESPONSE_LENGTH;    /* Long response */
      cmdreg |= SDHOST_CHECK_RESPONSE_CRC; /* Check response CRC */
    }
  else if (MMCSD_CMDRESP(cmd) == MMCSD_R3 || MMCSD_CMDRESP(cmd) == MMCSD_R4)
    {
      cmdreg |= SDHOST_RESPONSE_EXPECT;    /* Expect response, no CRC */
    }

  /* Data transfer */

  if (MMCSD_CMDDATA(cmd))
    {
      cmdreg |= SDHOST_DATA_EXPECTED;      /* Data expected */

      if (MMCSD_CMDWRITE(cmd))
        {
          cmdreg |= SDHOST_READ_WRITE;     /* Write operation */
        }
    }

  /* Wait for previous data transfer to complete */

  cmdreg |= SDHOST_WAIT_PRVDATA_COMPLETE;

  /* Set card number */

  cmdreg |= (priv->slot & 0x1fu) << SDHOST_CARD_NUMBER_S;

  /* Clear pending events */

  priv->events = 0;

  /* Send the command */

  esp_sdmmc_start_command(priv, cmdreg, arg);

  /* Wait for command done (with timeout) */

  ret = esp_sdmmc_wait_cmd_done(priv, 1000);
  if (ret < 0)
    {
      snerr("ERROR: Command %d failed: %d\n", MMCSD_CMDINDEX(cmd), ret);
      return ret;
    }

  return OK;
}

/****************************************************************************
