/****************************************************************************
 * Name: esp_sdmmc_cancel
 *
 * Description:
 *   Cancel any pending data transfer.
 *
 ****************************************************************************/

static int esp_sdmmc_cancel(struct sdio_dev_s *dev)
{
  struct esp32p4_sdmmc_dev_s *priv = (struct esp32p4_sdmmc_dev_s *)dev;
  sdmmc_dev_t *hw = SDMMC_HW;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  /* Reset DMA and FIFO via HAL */

  sdmmc_ll_reset_dma(hw);
  sdmmc_ll_reset_fifo(hw);

  /* Clear pending events */

  priv->events = 0;
  priv->waitevents = 0;

  spin_unlock_irqrestore(&priv->lock, flags);

  return OK;
}

