/****************************************************************************
 * Private Types
 ****************************************************************************/

/* DMA descriptor structure for ESP32P4 (64 bytes, cache-aligned).
 * This matches the hardware IDMAC descriptor layout.
 */

struct sdmmc_dma_desc_s
{
  volatile uint32_t des0;           /* Control word */
  volatile uint32_t des1;           /* Buffer sizes */
  volatile uint32_t buffer1_ptr;    /* Buffer 1 pointer */
  volatile uint32_t buffer2_ptr;    /* Buffer 2 pointer / next desc */
  volatile uint32_t reserved[12];   /* Padding to 64 bytes */
};

/* DMA descriptor des0 bit definitions */

#define DMA_DESC_OWN        (1u << 31)  /* Descriptor owned by IDMAC */
#define DMA_DESC_CH         (1u << 4)   /* Chain: second address is next desc */
#define DMA_DESC_FS         (1u << 3)   /* First descriptor of chain */
#define DMA_DESC_LD         (1u << 2)   /* Last descriptor of chain */
#define DMA_DESC_ER         (1u << 1)   /* End of ring */

/* SDMMC device structure extending struct sdio_dev_s */

/****************************************************************************
 * Name: esp_sdmmc_setup_dma_transfer
 *
 * Description:
 *   Set up DMA descriptors for a data transfer using the internal DMA
 *   controller (IDMAC).
 *
 ****************************************************************************/

static void esp_sdmmc_setup_dma_transfer(struct esp32p4_sdmmc_dev_s *priv,
                                          uint8_t *buffer, size_t len,
                                          bool is_tx)
{
  struct sdmmc_dma_desc_s *desc = priv->dma_desc;
  sdmmc_dev_t *hw = SDMMC_HW;

  /* Configure DMA descriptor */

  memset(desc, 0, sizeof(*desc));

  desc->des0 = DMA_DESC_OWN | DMA_DESC_FS | DMA_DESC_LD;
  if (is_tx)
    {
      desc->des0 |= DMA_DESC_CH;
    }

  desc->des1 = len & 0x1fffu;  /* Buffer 1 size (13 bits) */
  desc->buffer1_ptr = (uint32_t)buffer;
  desc->buffer2_ptr = 0;  /* No second buffer (single descriptor) */

  /* Set data transfer length */

  hw->bytcnt.val = len;
  hw->blksiz.val = SDMMC_DMA_MAX_BUF_LEN;

  /* Point DMA to descriptor */

  hw->dbaddr.val = (uint32_t)desc;

  /* Start DMA by writing to PLDMND */

  hw->pldmnd.val = 1;
}

